'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {ctx:c}=require('./native-fixtures-20261003.cjs').environment(),C=c.JYLiurenCompletion,results=[];
const base={date:'2026-10-03',time:'12:00',question:'工作',timezoneOffset:8},cast=(extra={})=>c.JYLiurenCore.calculate({...base,...extra});
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
test('四立前十八日半開邊界；初秋與整月土旺政策分立',()=>{
 const r=cast(),s=r.seasonal;assert.equal(s.activeElement,'金');assert.equal(Date.parse(s.earth18Interval.endExclusive)-Date.parse(s.earth18Interval.start),18*86400000);
 const lunar=c.Solar.fromYmdHms(2026,10,20,12,0,0).getLunar(),t=Date.parse(s.earth18Interval.start);
 assert.equal(C.seasonal(lunar,t-1,'戌').activeElement,'金');assert.equal(C.seasonal(lunar,t,'戌').activeElement,'土');assert.equal(C.seasonal(lunar,Date.parse(s.earth18Interval.endExclusive),'亥').activeElement,'水');
 assert.equal(cast({date:'2026-10-09',seasonPolicy:'whole-month'}).seasonal.activeElement,'土');assert.equal(cast({date:'2026-10-09'}).seasonal.activeElement,'金');
});
test('旺相休囚死依當選土旺政策进入64課條件',()=>{const a=cast({date:'2026-10-09'}),b=cast({date:'2026-10-09',seasonPolicy:'whole-month'});assert.equal(a.classAnalysis.checks.length,64);assert.equal(a.calendarContext.seasonElementIndex,3);assert.equal(b.calendarContext.seasonElementIndex,2);assert.equal(a.seasonal.states.土,'休');assert.equal(b.seasonal.states.土,'旺');});
test('日出日落對照獨立Swiss Ephemeris，海平面標準折射誤差小於60秒',()=>{const r=cast({longitude:121.56,latitude:25.03,nobleMode:'astronomical'});const a=r.clock.astronomy;assert.equal(a.daytime,true);assert.equal(r.noble.mode,'day');assert(Math.abs(Date.parse(a.previousRise)-Date.parse('2026-10-02T21:46:31.187Z'))<60000);assert(Math.abs(Date.parse(a.nextSet)-Date.parse('2026-10-03T09:38:53.959Z'))<60000);});
test('日出／日落前後一秒貴人晝夜切换',()=>{const a=cast({longitude:121.56,latitude:25.03}).clock.astronomy;for(const [event,before,after]of [[a.previousRise,false,true],[a.nextSet,true,false]]){for(const [delta,expected]of [[-1000,before],[1000,after]]){const ms=Date.parse(event)+delta,w=new Date(ms+8*3600000),r=cast({date:w.toISOString().slice(0,10),time:w.toISOString().slice(11,19),longitude:121.56,latitude:25.03,nobleMode:'astronomical'});assert.equal(r.daytime,expected);}}});
test('無坐標與極圈不捏造日出時刻，手動晝夜仍能排盤',()=>{assert.equal(cast().clock.astronomy.status,'coordinates-unavailable');assert.throws(()=>cast({nobleMode:'astronomical'}),/經緯度/);const r=cast({date:'2026-06-21',latitude:80,longitude:20,nobleMode:'day'});assert.equal(r.clock.astronomy.daytime,null);assert.equal(r.daytime,true);});
test('真太陽時固定原瞬間；真鐘跨日重新計算日柱且不挪交節',()=>{const r=cast({date:'2026-10-03',time:'00:02',longitude:90,trueSolarTime:true});assert.equal(r.time.instant,'2026-10-02T16:02:00.000Z');assert.equal(r.clock.corrected.day,2);assert.equal(r.day.ganzhi,'己酉');assert.equal(r.monthGeneral.branch,cast({time:'00:02'}).monthGeneral.branch);assert.throws(()=>cast({trueSolarTime:true}),/經度/);});
test('實際寒露瞬間分段；一日內丁酉與戊戌月不混為整日',()=>{const r=cast({timeWindow:{start:'2026-10-08',end:'2026-10-08'}}),d=r.timing.inspectedDays[0];assert.equal(d.dayGanzhi,'乙卯');assert.equal(d.monthSegments.length,2);assert.equal(d.monthSegments[0].monthGanzhi,'丁酉');assert.equal(d.monthSegments[1].monthGanzhi,'戊戌');assert.equal(d.monthSegments[0].endExclusive,'2026-10-08T06:29:17.000Z');assert.equal(d.monthSegments[0].endExclusive,d.monthSegments[1].start);});
test('00／23换日应期区间不同，真太阳逆解不丢分钟',()=>{const extra={timeWindow:{start:'2026-10-08',end:'2026-10-08'}},a=cast({...extra,dayBoundaryMode:'MIDNIGHT_00'}),b=cast({...extra,dayBoundaryMode:'ZI_HOUR_23'}),d=cast({...extra,longitude:90,trueSolarTime:true});assert.equal(Date.parse(a.timing.inspectedDays[0].start)-Date.parse(b.timing.inspectedDays[0].start),3600000);assert(Math.abs(Date.parse(d.timing.inspectedDays[0].start)-Date.parse(a.timing.inspectedDays[0].start))>3600000);});
test('客观值日／冲合候选均来自实排日干支，不排序成保证发生日',()=>{const r=cast({targetKinship:'官鬼'});for(const d of r.timing.candidates){assert.equal(d.dayGanzhi.length,2);for(const t of d.conditions){assert(r.plate.some(p=>p.branch===t.branch&&p.kinship==='官鬼'));assert(t.monthConstraints.length>=1);for(const w of t.why)if(/值日|填實旬空/.test(w.id))assert.equal(d.dayGanzhi[1],t.branch);}}});
test('只在真实离旬日列首次出旬；远期窗口不伪造首次离旬',()=>{const r=cast({date:'2026-10-02',timeWindow:{start:'2026-10-03',end:'2026-10-10'},targetKinship:'妻財'});for(const d of r.timing.candidates)for(const t of d.conditions)if(t.why.some(x=>x.id==='首次出原旬'))assert.equal(d.date,'2026-10-07');const distant=cast({date:'2026-10-02',timeWindow:{start:'2027-01-01',end:'2027-01-05'},targetKinship:'妻財'});assert(!distant.timing.candidates.some(d=>d.conditions.some(t=>t.why.some(x=>x.id==='首次出原旬'))));});
test('未明议题、多议题与过去窗口保持实际状态',()=>{assert.equal(cast({question:'看看'}).timing.status,'unresolved-topic');assert.equal(cast({question:'2024年工作'}).timing.status,'past-window');const r=cast({question:'工作与合同收入'});assert.equal(r.timing.selection.targets.length,3);});
test('同一计算结果进入原生JSON及提示词',()=>{const r=cast({longitude:121.56,latitude:25.03,nobleMode:'astronomical'}),n=c.JYNativeAnalysis.analyze('liuren',r),p=c.JYLiurenPrompt.build(r);assert.equal(n.coverage.timingDays,r.timing.inspectedDays.length);assert.equal(n.seasonal.profile,'earth18');assert(p.includes('monthSegments'));assert(p.includes(r.clock.astronomy.nextSet));assert(!/NaN|undefined/.test(p));});
test('無效／倒置日期拒絕；土旺十八日邊界所在日以實際時刻分段',()=>{
 assert.throws(()=>cast({timeWindow:{start:'2026-02-30',end:'2026-10-04'}}),/無效/);assert.throws(()=>cast({timeWindow:{start:'2026-10-05',end:'2026-10-04'}}),/早於/);
 const start=cast().seasonal.earth18Interval.start,day=new Date(Date.parse(start)+8*3600000).toISOString().slice(0,10),r=cast({timeWindow:{start:day,end:day}}),segments=r.timing.inspectedDays[0].monthSegments;assert(segments.length>=2);assert(segments.some(s=>s.endExclusive===start));assert(segments.some(s=>s.start===start));
});
fs.writeFileSync(path.join(__dirname,'../docs/liuren-completion-validation-20261003.json'),JSON.stringify({testedAt:new Date().toISOString(),passed:results.length,failed:0,independentEphemeris:'Swiss Ephemeris2.10.03 rise_trans sea level 0m, atmospheric pressure auto,15C at25.03N121.56E; not distributed with the application',results},null,2));
